row(9, 1, 'MATERIAL', f'HEAR, O ISRAEL: YOU ARE PASSING OVER THE JORDAN TODAY TO GO IN TO DISPOSSESS NATIONS GREATER AND MIGHTIER THAN YOU, CITIES GREAT AND FORTIFIED TO THE HEAVENS. {HP(9, 1, (("שמע", "ישראל"), "hear, O Israel — the book\'s four seats (5:1, 6:4, 9:1, 20:3; computed)"), (("אתה", "עבר", "היום", "את", "הירדן"), "you are passing over the Jordan today — the singular \'you\' of 9:1-6"), (("גוים", "גדלים", "ועצמים", "ממך"), "nations greater and mightier than you — 4:38 and 9:1 the two seats"), (("ערים", "גדלת", "ובצרת", "בשמים"), "cities great and fortified to the heavens — 1:28\'s phrase, spelled defective here and plene there (the census)"))} {AP(9, 1, (("למעל", "למירת"), "to enter to possess"), (("עממין", "רברבין", "ותקיפין"), "peoples great and strong"), (("עד", "צית", "שמיא"), "to the HEIGHT of heaven — the hyperbole softened, as at 1:28 and 4:11 (the three seats)"))} The Sifrei 25:4 reads the verse as Scripture\'s own hyperbole (the shelf below).')
row(9, 2, 'MATERIAL', f'A PEOPLE GREAT AND TALL, THE SONS OF THE ANAKIM, WHOM YOU KNOW AND OF WHOM YOU HAVE HEARD: WHO CAN STAND BEFORE THE SONS OF ANAK? {HP(9, 2, (("עם", "גדול", "ורם", "בני", "ענקים"), "a people great and tall, the sons of the Anakim — 1:28\'s words, the two seats of both phrases"), (("מי", "יתיצב", "לפני", "בני", "ענק"), "who can stand before the sons of Anak — the Torah\'s one \'who can stand before\' (Proverbs 22:29 the kin)"))} {AP(9, 2, (("עם", "רב", "ותקיף"), "a people many and strong"), (("בני", "גבריא"), "the sons of the GIANTS — the Anakim made giants (9:2 alone; the word\'s eight seats the book\'s mighty men)"), (("מן", "יכול", "למיקם", "קדם"), "who is able to stand before"))}')
row(9, 3, 'MATERIAL', f'AND YOU SHALL KNOW TODAY THAT THE LORD YOUR GOD IS HE WHO PASSES OVER BEFORE YOU, A CONSUMING FIRE; HE WILL DESTROY THEM AND HE WILL SUBDUE THEM BEFORE YOU, AND YOU SHALL DISPOSSESS THEM AND DESTROY THEM QUICKLY, AS THE LORD SPOKE TO YOU. {HP(9, 3, (("הוא", "העבר", "לפניך"), "He who passes over before you — the article\'s form 9:3 alone; 31:3 without it"), (("אש", "אכלה", "הוא"), "a consuming fire is He — 4:24\'s words (the two seats in the book)"), (("ישמידם", "והוא", "יכניעם"), "He will destroy them and subdue them — \'subdue\' the lemma\'s one seat in the book"), (("והורשתם", "והאבדתם", "מהר"), "and you shall dispossess and destroy them quickly — the consecutive perfects, the law\'s form at the opening only"))} {AP(9, 3, (("הוא", "דעבר", "קדמך"), "He who passes before you"), (("מימריה", "אשא", "אכלא"), "HIS WORD is a consuming fire — the Memra supplied for \'He\', as at 4:24 (the two seats of the phrase; His Memra ten seats in the book)"), (("ותתרכנון", "ותובדנון", "בפריע"), "and you shall drive them out and destroy them quickly"))}')
row(9, 4, 'MATERIAL', f'DO NOT SAY IN YOUR HEART, WHEN THE LORD YOUR GOD THRUSTS THEM OUT FROM BEFORE YOU, SAYING: FOR MY RIGHTEOUSNESS THE LORD HAS BROUGHT ME IN TO POSSESS THIS LAND — WHEREAS FOR THE WICKEDNESS OF THESE NATIONS THE LORD IS DISPOSSESSING THEM FROM BEFORE YOU. {HP(9, 4, (("אל", "תאמר", "בלבבך"), "do not say in your heart — the one seat of the bar; 8:17\'s \'and you say in your heart\' its kin"), (("בהדף", "יהוה", "אלהיך", "אתם"), "when the LORD your God thrusts them out — the lemma\'s one seat in the book\'s narrative (6:19 the other)"), (("בצדקתי", "הביאני", "יהוה"), "for my righteousness the LORD has brought me — the boaster\'s first person, the chapter\'s only \'I\' not Moses\'"), (("וברשעת", "הגוים", "האלה"), "and for the wickedness of these nations — the noun\'s Torah seats 9:4, 9:5, 25:2"))} {AP(9, 4, (("בדיתבר", "יי", "אלהך", "יתהון"), "when the LORD your God SMASHES them — the thrusting made a breaking"), (("בזכותי", "אעלני", "יי"), "by my MERIT the LORD brought me in — merit for righteousness (9:4-6 three of the book\'s five merit seats)"), (("ובחובי", "עממיא", "האלין"), "and for the SINS of these peoples — wickedness made sins"))}')
row(9, 5, 'MATERIAL', f'NOT FOR YOUR RIGHTEOUSNESS NOR FOR THE UPRIGHTNESS OF YOUR HEART DO YOU GO IN TO POSSESS THEIR LAND, BUT FOR THE WICKEDNESS OF THESE NATIONS THE LORD YOUR GOD IS DISPOSSESSING THEM FROM BEFORE YOU, AND IN ORDER TO ESTABLISH THE WORD WHICH THE LORD SWORE TO YOUR FATHERS, TO ABRAHAM, TO ISAAC AND TO JACOB. {HP(9, 5, (("לא", "בצדקתך", "ובישר", "לבבך"), "not for your righteousness nor the uprightness of your heart — \'uprightness of heart\' 9:5 and Psalm 119:7 alone"), (("ולמען", "הקים", "את", "הדבר"), "and in order to establish the word — the chapter\'s one \'so that\' (the book\'s forty-three)"), (("אשר", "נשבע", "יהוה", "לאבתיך"), "which the LORD swore to your fathers — \'swore\' the seven-stem homograph, no number (the parser)"), (("לאברהם", "ליצחק", "וליעקב"), "to Abraham, to Isaac and to Jacob — eleven seats of the three names in this order; 9:27 the chapter\'s second"))} {AP(9, 5, (("לא", "בזכותך", "ובקשיטות", "לבך"), "not by your merit nor the uprightness of your heart"), (("ובדיל", "לאקמא", "ית", "פתגמא"), "and in order to establish the word"), (("די", "קיים", "יי", "לאבהתך"), "which the LORD ESTABLISHED to your fathers — \'swore\' made \'established\', as at 7:8 and 8:1 (twenty-two seats)"))} THE THREE REASONS: the nations\' wickedness, the word sworn, and (9:6) the stiff neck — the second-person singular throughout 9:1-6.')
row(9, 6, 'MATERIAL', f'AND YOU SHALL KNOW THAT NOT FOR YOUR RIGHTEOUSNESS IS THE LORD YOUR GOD GIVING YOU THIS GOOD LAND TO POSSESS IT, FOR YOU ARE A STIFF-NECKED PEOPLE. {HP(9, 6, (("וידעת", "כי", "לא", "בצדקתך"), "and you shall know that not for your righteousness — the third \'righteousness\' of three verses"), (("את", "הארץ", "הטובה", "הזאת"), "this good land — 4:22\'s words (seven seats of \'the good land\')"), (("כי", "עם", "קשה", "ערף", "אתה"), "for you are a stiff-necked people — Exodus 33:3\'s clause word for word; STIFF-NECKED six seats in the Bible, all the calf\'s"))} {AP(9, 6, (("לא", "בזכותך"), "not by your merit"), (("ארעא", "טבתא", "הדא"), "this good land"), (("עם", "קשי", "קדל", "את"), "you are a people hard of neck — the idiom kept literal (9:6, 9:13)"))}')
row(9, 7, 'MATERIAL', f'REMEMBER, DO NOT FORGET, HOW YOU PROVOKED THE LORD YOUR GOD IN THE WILDERNESS: FROM THE DAY YOU WENT OUT OF THE LAND OF EGYPT UNTIL YOU CAME TO THIS PLACE YOU HAVE BEEN REBELLIOUS WITH THE LORD. {HP(9, 7, (("זכר", "אל", "תשכח"), "remember, do not forget — the one seat of the pair; the imperative \'remember\' 9:7, 9:27, 32:7 in the book"), (("את", "אשר", "הקצפת", "את", "יהוה"), "how you (sg.) provoked the LORD — the hiphil\'s Torah seats 9:7, 8, 22, all this chapter\'s"), (("למן", "היום", "אשר", "יצאת"), "from the day you went out — \'from the day\' 4:32 and 9:7 in the book"), (("עד", "באכם", "עד", "המקום", "הזה"), "until you (PL.) came to this place — THE REGISTER SWITCHES INSIDE THE VERSE (11:5 and 1:31 the phrase\'s kin)"), (("ממרים", "הייתם", "עם", "יהוה"), "you have been rebellious with the LORD — 9:7 and 9:24 the two seats, the participle"))} {AP(9, 7, (("הוי", "דכיר", "לא", "תנשי"), "be mindful, do not forget"), (("די", "ארגזתא", "קדם", "יי"), "how you angered BEFORE the LORD — the object made \'before\' (the reverence; 7, 8, 22)"), (("מסרבין", "הויתון", "קדם", "יי"), "you have been rebellious before the LORD"))}')
row(9, 8, 'MATERIAL', f'AND AT HOREB YOU PROVOKED THE LORD, AND THE LORD WAS ANGRY WITH YOU, TO DESTROY YOU. {HP(9, 8, (("ובחרב", "הקצפתם", "את", "יהוה"), "and at Horeb you provoked the LORD — the plural from here to 9:25; Horeb the calf\'s mountain (the Sifrei 342:1 quotes the clause among the harsh words)"), (("ויתאנף", "יהוה", "בכם"), "and the LORD was angry with you — the hithpael\'s four book seats (1:37, 4:21 Moses\'; 9:8, 9:20)"), (("להשמיד", "אתכם"), "to destroy you — 9:8, 19, 25 the three"))} {AP(9, 8, (("ובחרב", "ארגזתון", "קדם", "יי"), "and at Horeb you angered before the LORD"), (("והוה", "רגז", "מן", "קדם", "יי", "בכון"), "and there was anger FROM BEFORE the LORD against you — the anger distanced (1:37, 3:26, 9:8, 9:20 the four seats)"))}')
row(9, 9, 'MATERIAL', f'WHEN I WENT UP THE MOUNTAIN TO RECEIVE THE TABLETS OF STONE, THE TABLETS OF THE COVENANT WHICH THE LORD CUT WITH YOU, I STAYED ON THE MOUNTAIN FORTY DAYS AND FORTY NIGHTS; BREAD I DID NOT EAT AND WATER I DID NOT DRINK. {HP(9, 9, (("בעלתי", "ההרה", "לקחת"), "when I went up the mountain to take — the one seat"), (("לוחת", "האבנים", "לוחת", "הברית"), "the tablets of stone, the tablets of the covenant — \'tablets\' PLENE here (9:9, 9:10, 10:1 alone); \'the tablets of the covenant\' the Bible\'s three seats, all this chapter\'s (Exodus: \'of the testimony\')"), (("אשר", "כרת", "יהוה", "עמכם"), "which the LORD cut with you — Exodus 24:8\'s clause, the blood\'s verse (five tokens shared)"), (("ארבעים", "יום", "וארבעים", "לילה"), "forty days and forty nights — [40, 40] the parser; the phrase\'s nine Bible seats, four in the chapter"), (("לחם", "לא", "אכלתי", "ומים", "לא", "שתיתי"), "bread I did not eat and water I did not drink — 9:9, 9:18 the first person; Exodus 34:28 the third"))} {AP(9, 9, (("לוחי", "אבניא", "לוחי", "קימא"), "the tablets of stone, the tablets of the covenant"), (("ארבעין", "יממין", "וארבעין", "לילון"), "forty days and forty nights"), (("לחמא", "לא", "אכלית", "ומיא", "לא", "אשתיתי"), "bread I did not eat and water I did not drink"))} The Sifrei 14:1 and 306:25 read the verse with Exodus 34:28 — Moses\' suffering for the Torah (the shelf below).')
row(9, 10, 'MATERIAL', f'AND THE LORD GAVE ME THE TWO TABLETS OF STONE WRITTEN WITH THE FINGER OF GOD, AND ON THEM ALL THE WORDS WHICH THE LORD SPOKE WITH YOU ON THE MOUNTAIN FROM THE MIDST OF THE FIRE ON THE DAY OF THE ASSEMBLY. {HP(9, 10, (("את", "שני", "לוחת", "האבנים"), "the two tablets of stone — [2] the parser; plene again"), (("כתבים", "באצבע", "אלהים"), "written with the finger of God — Exodus 31:18\'s three tokens, the two seats; \'the finger of God\' Exodus 8:15 the magicians\' the only other; \'written\' the passive participle"), (("ככל", "הדברים", "אשר", "דבר", "יהוה", "עמכם"), "all the words which the LORD spoke with you — 10:4\'s clause (ten tokens shared)"), (("בהר", "מתוך", "האש", "ביום", "הקהל"), "on the mountain from the midst of the fire on the day of the assembly — \'the day of the assembly\' 9:10, 10:4, 18:16"))} {AP(9, 10, (("תרין", "לוחי", "אבניא"), "the two tablets of stone"), (("כתיבין", "באצבעא", "דיי"), "written with the finger OF THE LORD — \'God\' made the Name"), (("מגו", "אשתא", "ביומא", "דקהלא"), "from the midst of the fire on the day of the assembly — the mountain\'s fire \'eshata\'"))}')
row(9, 11, 'MATERIAL', f'AND IT CAME TO PASS AT THE END OF FORTY DAYS AND FORTY NIGHTS THAT THE LORD GAVE ME THE TWO TABLETS OF STONE, THE TABLETS OF THE COVENANT. {HP(9, 11, (("ויהי", "מקץ", "ארבעים", "יום"), "at the end of forty days — Genesis 8:6 (the ark\'s window) and Numbers 13:25 (the spies\' return) the kin"), (("את", "שני", "לחת", "האבנים"), "the two tablets of stone — \'tablets\' DEFECTIVE here (Exodus\'s spelling at every seat)"), (("לחות", "הברית"), "the tablets of the covenant — the SECOND PLENE, 4:13 and 1 Kings 8:9 its only kin: TWO SPELLINGS IN ONE VERSE"))} {AP(9, 11, (("והוה", "מסוף", "ארבעין", "יממין"), "and at the end of forty days"), (("תרין", "לוחי", "אבניא", "לוחי", "קימא"), "the two tablets of stone, the tablets of the covenant — one Aramaic spelling for three Hebrew ones"))}')
row(9, 12, 'MATERIAL', f'AND THE LORD SAID TO ME: ARISE, GO DOWN QUICKLY FROM HERE, FOR YOUR PEOPLE WHOM YOU BROUGHT OUT OF EGYPT HAVE CORRUPTED; THEY HAVE TURNED ASIDE QUICKLY FROM THE WAY WHICH I COMMANDED THEM; THEY HAVE MADE THEMSELVES A MOLTEN IMAGE. {HP(9, 12, (("ויאמר", "יהוה", "אלי"), "and the LORD said to me — a divine frame INSIDE the retelling (9:12, 9:13): Exodus 32:7-9 quoted"), (("קום", "רד", "מהר", "מזה"), "arise, go down quickly from here — Exodus 32:7 \'go, get down\'; \'quickly\' the infinitive absolute (four in the chapter)"), (("כי", "שחת", "עמך"), "for your people have corrupted — Exodus 32:7\'s clause (the two seats)"), (("סרו", "מהר", "מן", "הדרך", "אשר", "צויתם"), "they have turned aside quickly from the way which I commanded them — Exodus 32:8\'s eight tokens (Judges 2:17 the third)"), (("עשו", "להם", "מסכה"), "they have made them a molten image — the calf unnamed here (9:16 names it)"))} {AP(9, 12, (("קום", "חות", "בפריע", "מכא"), "arise, go down quickly from here"), (("ארי", "חביל", "עמך"), "for your people have corrupted"), (("עבדו", "להון", "מתכא"), "they have made them a molten thing"))}')
row(9, 13, 'MATERIAL', f'AND THE LORD SAID TO ME, SAYING: I HAVE SEEN THIS PEOPLE, AND BEHOLD, IT IS A STIFF-NECKED PEOPLE. {HP(9, 13, (("ויאמר", "יהוה", "אלי", "לאמר"), "and the LORD said to me, saying — the second frame; \'to me, saying\' the only change from Exodus 32:9\'s \'to Moses\'"), (("ראיתי", "את", "העם", "הזה"), "I have seen this people — the two seats"), (("והנה", "עם", "קשה", "ערף", "הוא"), "and behold, it is a stiff-necked people — ELEVEN OF THIRTEEN tokens shared with Exodus 32:9: the chapter\'s closest row"))} {AP(9, 13, (("גלי", "קדמי", "ית", "עמא", "הדין"), "it is REVEALED BEFORE ME — \'I have seen\' made the passive of revelation (31:21, 32:20 the kin)"), (("והא", "עם", "קשי", "קדל", "הוא"), "and behold, a people hard of neck it is"))}')
row(9, 14, 'MATERIAL', f'LET ME ALONE, AND I WILL DESTROY THEM AND BLOT OUT THEIR NAME FROM UNDER HEAVEN; AND I WILL MAKE OF YOU A NATION MIGHTIER AND MORE NUMEROUS THAN THEY. {HP(9, 14, (("הרף", "ממני"), "let Me alone — the one seat of the form; Exodus 32:10\'s \'let Me be\' another verb"), (("ואשמידם", "ואמחה", "את", "שמם"), "and I will destroy them and blot out their name — the cohortatives"), (("מתחת", "השמים"), "from under heaven — 7:24\'s and 25:19\'s phrase (eight seats)"), (("ואעשה", "אותך", "לגוי", "עצום", "ורב", "ממנו"), "and I will make of you a nation mightier and more numerous than they — THE OFFER\'S THIRD FORM (Exodus 32:10 \'a great nation\'; Numbers 14:12 \'greater and mightier than it\')"))} {AP(9, 14, (("אנח", "בעותך", "מקדמי"), "LEAVE YOUR PRAYER from before Me — the prayer SUPPLIED for \'let Me alone\' (Exodus 32:10\'s Onkelos the same)"), (("ואמחי", "ית", "שמהון", "מתחות", "שמיא"), "and I will blot out their name from under heaven"), (("לעם", "תקיף", "וסגי", "מנהון"), "a people strong and many more than they"))} The Sifrei 27:2 reads the clause as the door God opened for Moses\' prayer (the shelf below).')

